fn mirror_delete_pass(
    dst_root: &Path,
    source_files: &HashSet<String>,
    raw_entries: &[crate::mirror_planner::RawNamedEntry],
    shielded: &HashSet<String>,
    filter: &crate::fs_enum::FileFilter,
    pruned: &[String],
    tolerate_nonempty_dirs: bool,
    canonical_dst_root: Option<&Path>,
    abort: &AtomicBool,
    execute: bool,
    removed: &mut dyn FnMut(&Path, bool),
) -> Result<(u64, u64)> {
    let filter = crate::transfers::filter::destination_scope(filter, dst_root, pruned);
    let plan = crate::mirror_planner::MirrorPlanner::new(false).plan_session_deletions(
        dst_root,
        source_files,
        raw_entries,
        shielded,
        crate::raw_name::destination_can_store_raw_names(),
        &filter,
    )?;
    // review otp-9b F2: a dropped session future (client disconnect,
    // CancelJob) cannot abort a running blocking task — the shared executor
    // checks this drop-guard before every filesystem operation.
    let stats = crate::deletion::execute_deletion_plan_reporting(
        &plan.files,
        &plan.dirs,
        crate::deletion::DeletionOptions {
            operation: "mirror delete",
            canonical_root: canonical_dst_root,
            abort: Some(abort),
            execute,
            directory_mode: crate::deletion::DirectoryMode::EmptyOnly {
                tolerate_nonempty: tolerate_nonempty_dirs,
            },
        },
        removed,
    )
    .map_err(eyre::Report::new)?;
    Ok((stats.files, stats.dirs))
}

async fn destination_session(
    transport: &mut FrameTransport,
    negotiated: Negotiated,
    dst_root: &Path,
    data_plane_host: Option<&str>,
    instruments: DestinationInstruments,
    local_apply: Option<local::LocalApply>,
) -> Result<DestinationOutcome> {
    let phase_trace = bind_session_phase_trace(
        instruments.session_phase_trace.clone(),
        &negotiated,
        SessionPhaseRole::Destination,
    );
    let small_file_probe = bind_small_file_probe(
        instruments.small_file_probe.clone(),
        &negotiated,
        SessionPhaseRole::Destination,
    );
    let result = destination_session_inner(
        transport,
        negotiated,
        dst_root,
        data_plane_host,
        instruments,
        local_apply,
        phase_trace.clone(),
        small_file_probe.clone(),
    )
    .await;
    flush_session_phase_trace(phase_trace.as_ref()).await;
    finish_small_file_probe(small_file_probe.as_ref()).await;
    result
}

